const FONT_B64 = "";

function base64ToArrayBuffer(base64){
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for(let i=0;i<binary.length;i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

async function initHandwriting(){
  try{
    const seconds = new Date().getSeconds();
    let penColor = '#004EB5'; // Azul por padrão (pares)
    
    if (seconds % 7 === 0) {
        penColor = '#10B981'; // Verde (múltiplos de 7)
    } else if (seconds % 2 !== 0) {
        penColor = '#d1342b'; // Vermelho (ímpares)
    }
    
    document.documentElement.style.setProperty('--marker-red', penColor);

    const buffer = base64ToArrayBuffer(FONT_B64);
    const font = opentype.parse(buffer);

    const fontFace = new FontFace('SimplyPleasures', buffer);
    await fontFace.load();
    document.fonts.add(fontFace);

    const FONT_SIZE = 150;
    const UNITS = font.unitsPerEm;
    const SCALE = FONT_SIZE / UNITS;
    const LINE_HEIGHT = FONT_SIZE * 0.92;
    const OVERHANG = FONT_SIZE * 0.32; // o quanto "Lima" ultrapassa a borda direita de "Prof Rubia"

    function measureWidth(text){
      return font.stringToGlyphs(text).reduce((w, g) => w + g.advanceWidth * SCALE, 0);
    }

    const line1Width = measureWidth("Prof Rubia");
    const line2Width = measureWidth("Lima");
    // desloca "Lima" o suficiente pra sua borda direita passar da borda direita de "Prof Rubia"
    const indentLine2 = (line1Width - line2Width) + OVERHANG;

    const LINES = [
      { text: "Prof Rubia", xOffset: 0,          yBaseline: 0 },
      { text: "Lima",       xOffset: indentLine2, yBaseline: LINE_HEIGHT }
    ];

    const svg = document.getElementById('handwriting-svg');
    const glyphEls = [];
    let maxRight = 0;

    LINES.forEach(line => {
      const glyphs = font.stringToGlyphs(line.text);
      let x = line.xOffset;
      glyphs.forEach(glyph => {
        const path = glyph.getPath(x, line.yBaseline, FONT_SIZE);
        const d = path.toPathData(2);
        if(d){
          const el = document.createElementNS('http://www.w3.org/2000/svg','path');
          el.setAttribute('d', d);
          el.setAttribute('class','glyph-stroke');
          el.setAttribute('stroke-width', (FONT_SIZE * 0.045).toFixed(2));
          svg.appendChild(el);
          glyphEls.push(el);
        }
        x += glyph.advanceWidth * SCALE;
      });
      maxRight = Math.max(maxRight, x);
    });

    const ascent = font.ascender * SCALE;
    const descent = font.descender * SCALE;
    const viewTop = -ascent;
    const viewBottom = LINES[LINES.length - 1].yBaseline - descent;
    svg.setAttribute('viewBox', `0 ${viewTop} ${maxRight} ${viewBottom - viewTop}`);

    const SPEED = 1500 / 1.1; // duração total da abertura aumentada em 10%
    const MIN_DUR = 90 * 1.1;
    const OVERLAP = 0.55;

    let cumulativeDelay = 0;
    glyphEls.forEach(el => {
      const len = el.getTotalLength();
      const dur = Math.max(MIN_DUR, (len / SPEED) * 1000);

      el.style.strokeDasharray = len;
      el.style.strokeDashoffset = len;

      const strokeAnim = el.animate(
        [{ strokeDashoffset: len }, { strokeDashoffset: 0 }],
        { duration: dur, delay: cumulativeDelay, easing: 'linear', fill: 'forwards' }
      );
      strokeAnim.onfinish = () => { el.style.fill = 'var(--marker-red)'; };

      cumulativeDelay += dur * OVERLAP;
    });

    const totalWriteMs = cumulativeDelay + MIN_DUR;
    document.documentElement.style.setProperty('--dur-write', (totalWriteMs / 1000).toFixed(2) + 's');

    document.getElementById('intro').classList.add('ready');
    watchArrowOverText();
  }catch(err){
    console.error('Falha ao carregar a fonte para a animação de escrita:', err);
    document.getElementById('intro').classList.add('ready');
    watchArrowOverText();
  }
}

/*
  Observa a posição real da seta amarela (.logo-sweep) a cada frame e dispara
  o desaparecimento do texto (classe .erase, que aciona --dur-text-fade) no
  exato momento em que a borda da seta alcança o texto — funciona certo em
  qualquer tamanho de tela, já que usa a posição renderizada de verdade
  (inclusive respeitando a curva de aceleração da animação da seta), em vez
  de tentar "adivinhar" um tempo fixo em segundos.
*/
function watchArrowOverText(){
  const arrow = document.querySelector('.logo-sweep');
  const textWrap = document.querySelector('.text-wrap');
  if(!arrow || !textWrap) return;

  function check(){
    applyIntroFastForward();
    const arrowRect = arrow.getBoundingClientRect();
    
    // Atualiza a máscara de recorte para seguir a traseira da seta amarela
    // SOMAMOS 200px (para a direita) para garantir que o corte aconteça debaixo da parte amarela sólida.
    document.documentElement.style.setProperty('--wipe-x', (arrowRect.left + 200) + 'px');

    const textRect = textWrap.getBoundingClientRect();
    if(arrowRect.right >= textRect.left && !textWrap.classList.contains('erase')){
      textWrap.classList.add('erase');
    }
    
    // Continua animando enquanto a seta não tiver saído completamente da tela pela direita
    if (arrowRect.left < window.innerWidth) {
        requestAnimationFrame(check);
    } else {
        document.body.style.overflow = '';
    }
  }
  requestAnimationFrame(check);
}


/*
  Clique/toque durante a abertura: NÃO deve fazer a seta amarela sumir
  (isso era causado pelo navegador iniciar um "drag fantasma" da imagem —
  corrigido via CSS com pointer-events/user-drag/user-select em intro.css).
  Em vez disso, o clique acelera a animação toda para ela terminar mais rápido,
  em vez de pular direto pro final (o que ficaria abrupto).
*/
let introFastForward = false;
const INTRO_FAST_RATE = 6;

function applyIntroFastForward(){
  if(!introFastForward) return;
  document.getAnimations().forEach(anim => {
    if (anim.playbackRate !== INTRO_FAST_RATE) {
      anim.playbackRate = INTRO_FAST_RATE;
    }
  });
}

function setupIntroFastForwardOnClick(){
  const introEl = document.getElementById('intro');
  if(!introEl) return;
  introEl.addEventListener('click', function(e){
    e.preventDefault();
    introFastForward = true;
    applyIntroFastForward();
  });
  introEl.addEventListener('touchstart', function(){
    introFastForward = true;
    applyIntroFastForward();
  }, { passive: true });
  document.addEventListener('keydown', function(e){
    introFastForward = true;
    applyIntroFastForward();
  });
}

if ('scrollRestoration' in history) {
  history.scrollRestoration = 'manual';
}
window.scrollTo(0, 0);

if (!sessionStorage.getItem('introPlayed')) {
    document.body.style.overflow = 'hidden';
    sessionStorage.setItem('introPlayed', 'true');
    setupIntroFastForwardOnClick();
    initHandwriting();
}

